#include "fixture_authorization_frame.h"
#include "synthetic_resource_contract.h"
#include <string.h>
#include <stdio.h>
#include <stdarg.h>
static const char*cases[]={"read_execution","prepare_enrolled","execute_enrolled","cancel_prepared","read_operation","execute_unknown","recover_unknown","revoke_before_claim","revoke_after_await","revoke_before_send"};
static const char*operations[]={"read_execution","prepare_execution","execute_execution","cancel_execution","read_operation","execute_execution","recover_operation","execute_execution","execute_execution","execute_execution"};
const char*ax_fixture_case_name(AxFixtureCase c){return c>=0&&c<AX_FIXTURE_CASE_COUNT?cases[c]:NULL;}
const char*ax_fixture_case_operation(AxFixtureCase c){return c>=0&&c<AX_FIXTURE_CASE_COUNT?operations[c]:NULL;}
void ax_fixture_authorization_wipe(AxFixtureAuthorization*v){if(v){volatile unsigned char*p=(volatile unsigned char*)v;for(size_t i=0;i<sizeof *v;i++)p[i]=0;}}
static int lower_hex(unsigned char c){return(c>='0'&&c<='9')||(c>='a'&&c<='f');}
static int hex(unsigned char c){return lower_hex(c)||(c>='A'&&c<='F');}
static int token(const char*text,int reviewer){const char*prefix=reviewer?"axm.desk.dsk.qualification.reviewer.":"axm.desk.dsk.qualification.requester.";size_t start=strlen(prefix);if(strnlen(text,256)!=start+64||strncmp(text,prefix,start))return 0;for(size_t i=start;i<start+64;i++)if(!lower_hex((unsigned char)text[i]))return 0;return 1;}
static int scenario(const AxFixtureScenario*s){if(!ax_fixture_case_name(s->case_id)||s->expected_version>2)return 0;size_t n=strnlen(s->request_id,sizeof s->request_id);if(!n||n>160)return 0;for(size_t i=0;i<n;i++){unsigned char c=(unsigned char)s->request_id[i];if(!((c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='_'||c=='-'))return 0;}if(strnlen(s->plan_id,sizeof s->plan_id)!=77||strncmp(s->plan_id,"release_plan_",13))return 0;for(size_t i=13;i<77;i++)if(!lower_hex((unsigned char)s->plan_id[i]))return 0;if(strnlen(s->client_request_id,37)!=36)return 0;for(size_t i=0;i<36;i++){if(i==8||i==13||i==18||i==23){if(s->client_request_id[i]!='-')return 0;}else if(!hex((unsigned char)s->client_request_id[i]))return 0;}unsigned char variant=(unsigned char)s->client_request_id[19];return s->client_request_id[14]=='4'&&(variant=='8'||variant=='9'||variant=='a'||variant=='b'||variant=='A'||variant=='B');}
static int valid(const AxFixtureAuthorization*v){if(!v||!token(v->requester_token,0)||!token(v->reviewer_token,1)||v->count<1||v->count>AX_FIXTURE_SCENARIOS_MAX)return 0;for(size_t i=0;i<v->count;i++)if(!scenario(&v->scenarios[i])||(i&&v->scenarios[i].case_id<=v->scenarios[i-1].case_id))return 0;return 1;}
typedef struct {const unsigned char*p;size_t n,i;} Json;
static void space(Json*j){while(j->i<j->n&&(j->p[j->i]==' '||j->p[j->i]=='\n'||j->p[j->i]=='\r'||j->p[j->i]=='\t'))j->i++;}
static int take(Json*j,unsigned char c){space(j);if(j->i>=j->n||j->p[j->i]!=c)return 0;j->i++;return 1;}
static int string(Json*j,char*out,size_t cap){if(!take(j,'"'))return 0;size_t used=0;while(j->i<j->n){unsigned char c=j->p[j->i++];if(c=='"'){if(used>=cap)return 0;out[used]=0;return 1;}if(c=='\\'){if(j->i>=j->n)return 0;c=j->p[j->i++];if(c=='u'){if(j->n-j->i<4)return 0;unsigned value=0;for(unsigned k=0;k<4;k++){unsigned char x=j->p[j->i++];if(!hex(x))return 0;value=value*16+(x<='9'?x-'0':(x|32)-'a'+10);}if(value>127)return 0;c=(unsigned char)value;}else if(c!='"'&&c!='\\'&&c!='/')return 0;}if(c<0x20||c>=0x80||used+1>=cap)return 0;out[used++]=(char)c;}return 0;}
static int number(Json*j,unsigned*out){space(j);if(j->i>=j->n||j->p[j->i]<'0'||j->p[j->i]>'2')return 0;*out=j->p[j->i++]-'0';return 1;}
static int entry(Json*j,AxFixtureScenario*out){if(!take(j,'{'))return 0;unsigned fields=0;for(;;){char key[32],value[64];if(!string(j,key,sizeof key)||!take(j,':'))return 0;unsigned bit=0;if(!strcmp(key,"caseId")){bit=1;if(!string(j,value,sizeof value))return 0;size_t i=0;for(;i<AX_FIXTURE_CASE_COUNT;i++)if(!strcmp(value,cases[i]))break;if(i==AX_FIXTURE_CASE_COUNT)return 0;out->case_id=(AxFixtureCase)i;}else if(!strcmp(key,"requestId")){bit=2;if(!string(j,out->request_id,sizeof out->request_id))return 0;}else if(!strcmp(key,"planId")){bit=4;if(!string(j,out->plan_id,sizeof out->plan_id))return 0;}else if(!strcmp(key,"expectedVersion")){bit=8;if(!number(j,&out->expected_version))return 0;}else if(!strcmp(key,"clientRequestId")){bit=16;if(!string(j,out->client_request_id,sizeof out->client_request_id))return 0;}else return 0;if(fields&bit)return 0;fields|=bit;space(j);if(take(j,'}'))break;if(!take(j,','))return 0;}return fields==31&&scenario(out);}
static int parse(const unsigned char*bytes,size_t n,AxFixtureAuthorization*out){Json j={bytes,n,0};if(!take(&j,'{'))return 0;unsigned fields=0;for(;;){char key[32],value[64];unsigned bit=0;if(!string(&j,key,sizeof key)||!take(&j,':'))return 0;if(!strcmp(key,"tenant")){bit=1;if(!string(&j,value,sizeof value)||strcmp(value,"qualification_workspace"))return 0;}else if(!strcmp(key,"requesterToken")){bit=2;if(!string(&j,out->requester_token,sizeof out->requester_token))return 0;}else if(!strcmp(key,"reviewerToken")){bit=4;if(!string(&j,out->reviewer_token,sizeof out->reviewer_token))return 0;}else if(!strcmp(key,"scenarios")){bit=8;if(!take(&j,'['))return 0;for(;;){if(out->count>=AX_FIXTURE_SCENARIOS_MAX||!entry(&j,&out->scenarios[out->count]))return 0;out->count++;if(take(&j,']'))break;if(!take(&j,','))return 0;}}else return 0;if(fields&bit)return 0;fields|=bit;if(take(&j,'}'))break;if(!take(&j,','))return 0;}space(&j);return fields==15&&j.i==j.n&&valid(out);}
int ax_fixture_authorization_decode(const unsigned char*in,size_t n,AxFixtureAuthorization*out){if(!out)return 0;ax_fixture_authorization_wipe(out);if(!in||n<AX_FIXTURE_AUTH_HEADER||n>AX_FIXTURE_AUTH_FRAME_MAX||memcmp(in,"AXQAUTH1",8)||memcmp(in+8,AX_SYNTH_GENERATION,32))return 0;uint32_t length=0;for(unsigned i=40;i<44;i++)length=(length<<8)|in[i];if(!length||length>AX_FIXTURE_AUTH_PAYLOAD_MAX||n!=AX_FIXTURE_AUTH_HEADER+length||!parse(in+44,length,out)){ax_fixture_authorization_wipe(out);return 0;}return 1;}
static int append(unsigned char*out,size_t cap,size_t*used,const char*format,...){if(*used>=cap)return 0;va_list args;va_start(args,format);int n=vsnprintf((char*)out+*used,cap-*used,format,args);va_end(args);if(n<0||(size_t)n>=cap-*used)return 0;*used+=(size_t)n;return 1;}
int ax_fixture_authorization_encode(const AxFixtureAuthorization*v,unsigned char*out,size_t cap,size_t*length){if(length)*length=0;if(!out||!length||cap<45||!valid(v))return 0;if(cap>AX_FIXTURE_AUTH_FRAME_MAX)cap=AX_FIXTURE_AUTH_FRAME_MAX;size_t used=44;if(!append(out,cap,&used,"{\"tenant\":\"qualification_workspace\",\"requesterToken\":\"%s\",\"reviewerToken\":\"%s\",\"scenarios\":[",v->requester_token,v->reviewer_token))return 0;for(size_t i=0;i<v->count;i++){const AxFixtureScenario*s=&v->scenarios[i];if(!append(out,cap,&used,"%s{\"caseId\":\"%s\",\"requestId\":\"%s\",\"planId\":\"%s\",\"expectedVersion\":%u,\"clientRequestId\":\"%s\"}",i?",":"",cases[s->case_id],s->request_id,s->plan_id,s->expected_version,s->client_request_id))return 0;}if(!append(out,cap,&used,"]}"))return 0;memcpy(out,"AXQAUTH1",8);memcpy(out+8,AX_SYNTH_GENERATION,32);uint32_t n=(uint32_t)(used-44);for(unsigned i=0;i<4;i++)out[40+i]=(unsigned char)(n>>(24-8*i));*length=used;return 1;}
int ax_fixture_scenario_request(const AxFixtureAuthorization*v,size_t index,unsigned char*out,size_t cap,size_t*length,unsigned*budget){if(length)*length=0;if(!length||!budget||!out||!valid(v)||index>=v->count)return 0;const AxFixtureScenario*s=&v->scenarios[index];const char*op=operations[s->case_id],*credential=v->requester_token;size_t used=0;int read=s->case_id==AX_FIXTURE_READ_EXECUTION||s->case_id==AX_FIXTURE_READ_OPERATION;*budget=s->case_id==AX_FIXTURE_READ_OPERATION||s->case_id==AX_FIXTURE_RECOVER_UNKNOWN?10000:25000;if(!append(out,cap,&used,"{\"protocol\":\"axiom.issuer-request/1\",\"operation\":\"%s\",\"requestId\":\"%s\",\"planId\":\"%s\",\"authorization\":\"%s\"",op,s->request_id,s->plan_id,credential))return 0;if(!read){const char*action=s->case_id==AX_FIXTURE_PREPARE_ENROLLED?"prepare":s->case_id==AX_FIXTURE_CANCEL_PREPARED?"cancel":s->case_id==AX_FIXTURE_RECOVER_UNKNOWN?"recover":"execute";if(!append(out,cap,&used,",\"body\":{\"action\":\"%s\",\"expectedVersion\":%u",action,s->expected_version))return 0;if(s->case_id!=AX_FIXTURE_RECOVER_UNKNOWN&&!append(out,cap,&used,",\"clientRequestId\":\"%s\"",s->client_request_id))return 0;if(!append(out,cap,&used,"}"))return 0;}if(!append(out,cap,&used,"}")||used>4096)return 0;*length=used;return 1;}

void ax_fixture_authorization_stream_wipe(AxFixtureAuthorizationStream*s){if(s){volatile unsigned char*p=s->bytes;for(size_t i=0;i<sizeof s->bytes;i++)p[i]=0;s->used=0;s->failed=1;}}
int ax_fixture_authorization_stream_feed(AxFixtureAuthorizationStream*s,const unsigned char*data,size_t n){if(!s||s->failed||s->ended||(!data&&n)||n>sizeof s->bytes-s->used){ax_fixture_authorization_stream_wipe(s);return 0;}memcpy(s->bytes+s->used,data,n);s->used+=n;if(s->used>=44){uint32_t length=0;for(unsigned i=40;i<44;i++)length=(length<<8)|s->bytes[i];if(memcmp(s->bytes,"AXQAUTH1",8)||memcmp(s->bytes+8,AX_SYNTH_GENERATION,32)||!length||length>65536||s->used>44U+length){ax_fixture_authorization_stream_wipe(s);return 0;}}return 1;}
int ax_fixture_authorization_stream_end(AxFixtureAuthorizationStream*s,AxFixtureAuthorization*out){if(!s||s->failed||s->ended||!out){if(out)ax_fixture_authorization_wipe(out);return 0;}s->ended=1;if(!ax_fixture_authorization_decode(s->bytes,s->used,out)){ax_fixture_authorization_stream_wipe(s);return 0;}return 1;}
